#!/bin/sh
# Generated by the Scalar SDK Generator. Edits here are overwritten on the next generation.
#
# Installs the standalone devcli executable from this project's GitHub releases:
#
#   curl -fsSL https://github.com/amritk/dev-cli/releases/latest/download/install.sh | bash
#
# Re-running it upgrades an existing install in place, and so does `devcli upgrade`: both download
# the archive built for this machine, verify it against the release's `checksums.txt`, and replace
# the executable with one atomic rename.
#
# Options, read from the environment, or the version as the first argument (`| bash -s -- 1.2.3`):
#   DEVCLI_VERSION       release to install, such as 1.2.3 (default: the latest release)
#   DEVCLI_INSTALL_DIR   directory to install into (default: $HOME/.local/bin)
#
# POSIX sh rather than bash, so `| sh` works as well as `| bash` on a system with no bash at all.
set -eu

BIN='devcli'
REPO='amritk/dev-cli'

# Everything runs from `main`, called on the script's last line. A download cut off partway leaves the
# shell holding a function it never reaches the call for, so a truncated script does nothing rather
# than running whichever commands happened to arrive.
main() {
  version="${1:-${DEVCLI_VERSION:-latest}}"
  install_dir="${DEVCLI_INSTALL_DIR:-${HOME:?HOME is not set; set DEVCLI_INSTALL_DIR instead}/.local/bin}"

  target="$(detect_target)"
  asset="${BIN}-${target}.tar.gz"
  if [ "$version" = latest ]; then
    base="https://github.com/${REPO}/releases/latest/download"
  else
    # Release tags carry a `v`; accept the version with or without one.
    base="https://github.com/${REPO}/releases/download/v${version#v}"
  fi

  staging="$(mktemp -d "${TMPDIR:-/tmp}/${BIN}-install.XXXXXX")"
  pending=''
  # An interrupt exits rather than resuming, so the EXIT trap is the one place the cleanup runs — and it
  # covers the file staged in the install directory too, so a failure between staging and the rename
  # does not leave an executable dotfile on PATH.
  trap 'rm -rf "$staging"; [ -z "$pending" ] || rm -f "$pending"' EXIT
  # HUP too: dash runs no EXIT trap when killed by a signal it does not trap, and closing the terminal
  # mid-install sends HUP.
  trap 'exit 1' HUP INT TERM

  say "Downloading ${asset}"
  fetch "${base}/${asset}" "${staging}/${asset}"
  fetch "${base}/checksums.txt" "${staging}/checksums.txt"

  # The same verification `upgrade` performs, so the first install is held to the bar every later one
  # is. An archive the release publishes no checksum for is refused, not installed unverified.
  expected="$(awk -v name="$asset" '$2 == name { print $1 }' "${staging}/checksums.txt")"
  [ -n "$expected" ] || fail "the release publishes no checksum for ${asset}"
  actual="$(sha256 "${staging}/${asset}")"
  [ "$actual" = "$expected" ] || fail "checksum mismatch for ${asset} (expected ${expected}, got ${actual})"

  tar -xzf "${staging}/${asset}" -C "$staging"
  [ -f "${staging}/${BIN}" ] || fail "${asset} did not contain the expected ${BIN} executable"

  mkdir -p "$install_dir"
  # Staged inside the install directory so the final `mv` is a rename within one filesystem: atomic,
  # and safe over a copy of the command that is running right now. Created by `mktemp`, which refuses
  # an existing name, rather than at a predictable one: `cp` and `chmod` follow a symlink, so under
  # `sudo` into a group-writable directory a link planted at a guessable name would choose a file for
  # root to overwrite.
  pending="$(mktemp "${install_dir}/.${BIN}.install.XXXXXX")"
  cat "${staging}/${BIN}" >"$pending"
  chmod 755 "$pending"

  # Run before it replaces anything, so a build this machine cannot execute — a 32-bit userland on a
  # 64-bit kernel reports a 64-bit `uname -m` — fails here and leaves a working install untouched.
  installed="$("$pending" --version 2>/dev/null)" ||
    fail "the downloaded ${BIN} does not run on this machine ($(uname -s) $(uname -m)); nothing was changed"
  mv -f "$pending" "${install_dir}/${BIN}"
  pending=''

  say "Installed ${BIN}${installed:+ ${installed}} to ${install_dir}/${BIN}"
  path_hint "$install_dir"
}

# Prints a progress line on stderr, keeping stdout free for anything piping this script's output.
say() {
  printf '%s\n' "$*" >&2
}

# Reports a failure and stops.
fail() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

# Maps this machine onto the release asset suffix the release step packs: `<os>-<arch>`.
detect_target() {
  case "$(uname -s)" in
    Darwin) os=darwin ;;
    Linux) os=linux ;;
    *) fail "no ${BIN} release is published for $(uname -s); on Windows, download ${BIN}-windows-x64.zip from https://github.com/${REPO}/releases/latest" ;;
  esac
  case "$(uname -m)" in
    x86_64 | amd64) arch=x64 ;;
    arm64 | aarch64) arch=arm64 ;;
    *) fail "no ${BIN} release is published for $(uname -m)" ;;
  esac
  # A shell running under Rosetta reports x86_64 on Apple Silicon. The native build is the one to
  # install there: it is faster, and it does not stop working if Rosetta is removed.
  if [ "$os" = darwin ] && [ "$arch" = x64 ] && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null || true)" = 1 ]; then
    arch=arm64
  fi
  # The Linux builds link against glibc, so on a musl system (Alpine) the executable would install
  # and then fail to start. Said up front instead.
  if [ "$os" = linux ] && ldd --version 2>&1 | grep -qi musl; then
    fail "the ${BIN} Linux release is built for glibc and does not run on musl"
  fi
  printf '%s-%s\n' "$os" "$arch"
}

# Downloads a URL to a file with curl, or wget where curl is missing. Fails on an HTTP error rather
# than saving the error page as the archive.
fetch() {
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL --retry 3 -o "$2" "$1" || fail "could not download $1"
  elif command -v wget >/dev/null 2>&1; then
    wget -q -O "$2" "$1" || fail "could not download $1"
  else
    fail "curl or wget is required to download ${BIN}"
  fi
}

# SHA-256 of a file: `sha256sum` on Linux, `shasum` on macOS.
sha256() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{ print $1 }'
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{ print $1 }'
  else
    fail "sha256sum or shasum is required to verify the download"
  fi
}

# Says how to put the install directory on PATH when it is not already, and names any other copy of
# the command that would run instead of this one.
path_hint() {
  case ":${PATH}:" in
    *":$1:"*)
      found="$(command -v "$BIN" 2>/dev/null || true)"
      if [ -n "$found" ] && [ "$found" != "$1/${BIN}" ]; then
        say "note: ${found} comes first on PATH, so \`${BIN}\` still runs that copy"
      fi
      ;;
    *)
      say ""
      say "$1 is not on your PATH. Add it by appending this line to your shell profile:"
      say "  export PATH=\"$1:\$PATH\""
      ;;
  esac
}

main "$@"
